8	/* -----------------------------------------------------------
9	  The core of the allocator. Every segment contains
10	  pages of a certain block size. The main function
11	  exported is `mi_malloc_generic`.
12	----------------------------------------------------------- */
13	
14	#include "mimalloc.h"
15	#include "mimalloc/internal.h"
16	#include "mimalloc/atomic.h"
17	#include "mimalloc/prim.h"
18	#include "mimalloc/prim-tls.h"
19	
20	/* -----------------------------------------------------------
21	  Definition of page queues for each block size
22	----------------------------------------------------------- */
23	
24	#define MI_IN_PAGE_C
25	#include "page-queue.c"
26	#undef MI_IN_PAGE_C
27	
28	
29	/* -----------------------------------------------------------
30	  Page helpers
31	----------------------------------------------------------- */
32	
33	// Index a block in a page
34	static inline mi_block_t* mi_page_block_at(const mi_page_t* page, void* page_start, size_t block_size, size_t i) {
35	  MI_UNUSED(page);
36	  mi_assert_internal(page != NULL);
37	  mi_assert_internal(i <= page->reserved);
38	  return (mi_block_t*)((uint8_t*)page_start + (i * block_size));
39	}
40	
41	static bool mi_page_extend_free(mi_theap_t* theap, mi_page_t* page);
42	
43	#if (MI_DEBUG>=3)
44	static size_t mi_page_list_count(mi_page_t* page, mi_block_t* head) {
45	  mi_assert_internal(_mi_ptr_page(mi_page_start(page)) == page);
46	  const uint8_t* slice_start = mi_page_slice_start(page);
47	  mi_assert_internal(_mi_is_aligned(slice_start,MI_PAGE_ALIGN));
48	  size_t count = 0;
49	  while (head != NULL) {
50	    mi_assert_internal((uint8_t*)head - slice_start > (ptrdiff_t)MI_LARGE_PAGE_SIZE || page == _mi_ptr_page(head));
51	    count++;
52	    head = mi_block_next(page, head);
53	  }
54	  return count;
55	}
56	
57	/*
58	// Start of the page available memory
59	static inline uint8_t* mi_page_area(const mi_page_t* page) {
60	  return _mi_page_start(_mi_page_segment(page), page, NULL);
61	}
62	*/
63	
64	static bool mi_page_list_is_valid(mi_page_t* page, mi_block_t* p) {
65	  size_t psize;
66	  uint8_t* page_area = mi_page_area(page, &psize);
67	  mi_block_t* start = (mi_block_t*)page_area;
68	  mi_block_t* end   = (mi_block_t*)(page_area + psize);
69	  while(p != NULL) {
70	    if (p < start || p >= end) return false;
71	    p = mi_block_next(page, p);
72	  }
73	#if MI_DEBUG>3 // generally too expensive to check this
74	  if (page->free_is_zero) {
75	    const size_t ubsize = mi_page_usable_block_size(page);
76	    for (mi_block_t* block = page->free; block != NULL; block = mi_block_next(page, block)) {
77	      mi_assert_expensive(mi_mem_is_zero(block + 1, ubsize - sizeof(mi_block_t)));
78	    }
79	  }
80	#endif
81	  return true;
82	}
83	
84	static bool mi_page_is_valid_init(mi_page_t* page) {
85	  mi_assert_internal(mi_page_block_size(page) > 0);
86	  mi_assert_internal(page->used <= page->capacity);
87	  mi_assert_internal(page->capacity <= page->reserved);
88	  
89	  mi_assert_internal(page->heap!=NULL);
90	  mi_theap_t* const page_theap = _mi_heap_theap_peek(page->heap);
91	  mi_assert_internal(page_theap == NULL || mi_page_theap(page)==page_theap || mi_page_theap(page)->tld->thread_id == MI_THREADID_DETACHED);
92	
93	  // const size_t bsize = mi_page_block_size(page);
94	  // uint8_t* start = mi_page_start(page);
95	  //mi_assert_internal(start + page->capacity*page->block_size == page->top);
96	
97	  mi_assert_internal(mi_page_list_is_valid(page,page->free));
98	  mi_assert_internal(mi_page_list_is_valid(page,page->local_free));
99	
100	  #if MI_DEBUG>3 // generally too expensive to check this
101	  if (page->free_is_zero) {
102	    const size_t ubsize = mi_page_usable_block_size(page);
103	    for(mi_block_t* block = page->free; block != NULL; block = mi_block_next(page,block)) {
104	      mi_assert_expensive(mi_mem_is_zero(block + 1, ubsize - sizeof(mi_block_t)));
105	    }
106	  }
107	  #endif 
108	
109	  #if !MI_TRACK_ENABLED && !MI_TSAN
110	  mi_block_t* tfree = mi_page_thread_free(page);
111	  mi_assert_internal(mi_page_list_is_valid(page, tfree));
112	  //size_t tfree_count = mi_page_list_count(page, tfree);
113	  //mi_assert_internal(tfree_count <= page->thread_freed + 1);
114	  #endif
115	
116	  size_t free_count = mi_page_list_count(page, page->free) + mi_page_list_count(page, page->local_free);
117	  mi_assert_internal(page->used + free_count == page->capacity);
118	
119	  return true;
120	}
121	
122	extern mi_decl_hidden bool _mi_process_is_initialized;             // has mi_process_init been called?
123	
124	bool _mi_page_is_valid(mi_page_t* page) {
125	  mi_assert_internal(mi_page_is_valid_init(page));
126	  #if MI_SECURE
127	  mi_assert_internal(page->keys[0] != 0);
128	  #endif
129	  if (!mi_page_is_abandoned(page)) {
130	    //mi_assert_internal(!_mi_process_is_initialized);
131	    mi_assert_internal(page->heap!=NULL);
132	    mi_theap_t* const page_theap = _mi_heap_theap_peek(page->heap);
133	    mi_assert_internal(page_theap == NULL || mi_page_theap(page)==page_theap || mi_page_theap(page)->tld->thread_id == MI_THREADID_DETACHED);
134	    {
135	      mi_page_queue_t* pq = mi_page_queue_of(page);
136	      mi_assert_internal(mi_page_queue_contains(pq, page));
137	      mi_assert_internal(pq->block_size==mi_page_block_size(page) || mi_page_is_huge(page) || mi_page_is_in_full(page));
138	      // mi_assert_internal(mi_theap_contains_queue(mi_page_theap(page),pq));
139	    }
140	  }
141	  return true;
142	}
143	#endif
144	
145	
146	/* -----------------------------------------------------------
147	  Page collect the `local_free` and `thread_free` lists
148	----------------------------------------------------------- */
149	
150	static void mi_page_thread_collect_to_local(mi_page_t* page, mi_block_t* head)
151	{
152	  if (head == NULL) return;
153	
154	  // find the last block in the list -- also to get a proper use count (without data races)
155	  size_t max_count = page->capacity; // cannot collect more than capacity
156	  size_t count = 1;
157	  mi_block_t* last = head;
158	  mi_block_t* next;
159	  while ((next = mi_block_next(page, last)) != NULL && count <= max_count) {
160	    count++;
161	    last = next;
162	  }
163	
164	  // if `count > max_count` there was a memory corruption (possibly infinite list due to double multi-threaded free)
165	  if mi_unlikely(count > max_count) {
166	    _mi_error_message(EFAULT, "corrupted thread-free list (possibly due to a cross-thread double free)\n");
167	    return; // the thread-free items cannot be freed
168	  }
169	  // if `count > page->used` there was another kind memory corruption (either in the page meta-data or in the linked list)
170	  else if mi_unlikely(count > page->used) {
171	    _mi_error_message(EFAULT, "corrupted meta-data in thread-free list\n");
172	    return; // the thread-free items cannot be freed
173	  }
174	
175	  // and append the current local free list
176	  mi_block_set_next(page, last, page->local_free);
177	  page->local_free = head;
178	
179	  // update counts now
180	  mi_assert_internal(count <= UINT16_MAX);
181	  mi_assert_internal(page->used >= (uint16_t)count);
182	  page->used = page->used - (uint16_t)count;
183	}
184	
185	// Collect the local `thread_free` list using an atomic exchange.
186	static void mi_page_thread_free_collect(mi_page_t* page)
187	{
188	  // atomically capture the thread free list
189	  mi_block_t* head;
190	  mi_thread_free_t tfreex;
191	  mi_thread_free_t tfree = mi_atomic_load_relaxed(&page->xthread_free);
192	  do {
193	    head = mi_tf_block(tfree);
194	    if mi_likely(head == NULL) return; // return if the list is empty
195	    tfreex = mi_tf_create(NULL,mi_tf_is_owned(tfree));  // set the thread free list to NULL
196	  } while (!mi_atomic_cas_weak_acq_rel(&page->xthread_free, &tfree, tfreex));  // release is enough?
197	  mi_assert_internal(head != NULL);
198	
199	  // and move it to the local list
200	  mi_page_thread_collect_to_local(page, head);
201	}
202	
203	// returns `true` if after collection `mi_page_immediate_available` is true.
204	static inline bool mi_page_free_quick_collect(mi_page_t* page) {
205	  if mi_likely(page->free != NULL) return true;
206	  if (page->local_free == NULL) return false;
207	  // move local_free to free
208	  page->free = page->local_free;
209	  page->local_free = NULL;
210	  page->free_is_zero = false;
211	  return true;
212	}
213	
214	void _mi_page_free_collect(mi_page_t* page, bool force) {
215	  mi_assert_internal(page!=NULL);
216	
217	  // collect the thread free list
218	  mi_page_thread_free_collect(page);
219	
220	  // and the local free list
221	  if (page->local_free != NULL) {
222	    if mi_likely(page->free == NULL) {
223	      // usual case
224	      page->free = page->local_free;
225	      page->local_free = NULL;
226	      page->free_is_zero = false;
227	    }
228	    else if (force) {
229	      // append -- only on shutdown (force) as this is a linear operation
230	      mi_block_t* tail = page->local_free;
231	      mi_block_t* next;
232	      while ((next = mi_block_next(page, tail)) != NULL) {
233	        tail = next;
234	      }
235	      mi_block_set_next(page, tail, page->free);
236	      page->free = page->local_free;
237	      page->local_free = NULL;
238	      page->free_is_zero = false;
239	    }
240	  }
241	
242	  mi_assert_internal(!force || page->local_free == NULL);
243	}
244	
245	// Collect elements in the thread-free list starting at `head`. This is an optimized
246	// version of `_mi_page_free_collect` to be used from `free.c:_mi_free_collect_mt` that avoids atomic access to `xthread_free`.
247	//
248	// `head` must be in the `xthread_free` list. It will not collect `head` itself
249	// so the `used` count is not fully updated in general. However, if the `head` is
250	// the last remaining element, it will be collected and the used count will become `0` (so `mi_page_all_free` becomes true).
251	void _mi_page_free_collect_partly(mi_page_t* page, mi_block_t* head) {
252	  if (head == NULL) return;
253	  mi_block_t* next = mi_block_next(page,head);  // we cannot collect the head element itself as `page->thread_free` may point to it (and we want to avoid atomic ops)
254	  if (next != NULL) {
255	    mi_block_set_next(page, head, NULL);
256	    mi_page_thread_collect_to_local(page, next);
257	    if (page->local_free != NULL && page->free == NULL) {
258	      page->free = page->local_free;
259	      page->local_free = NULL;
260	      page->free_is_zero = false;
261	    }
262	  }
263	  if (page->used == 1) {
264	    // all elements are free'd since we skipped the `head` element itself
265	    mi_assert_internal(mi_tf_block(mi_atomic_load_relaxed(&page->xthread_free)) == head);
266	    mi_assert_internal(mi_block_next(page,head) == NULL);
267	    _mi_page_free_collect(page, false);  // collect the final element
268	  }
269	}
270	
271	
272	/* -----------------------------------------------------------
273	  Page fresh and retire
274	----------------------------------------------------------- */
275	
276	// called from `mi_free` on a reclaim, and fresh_alloc if we get an abandoned page
277	void _mi_theap_page_reclaim(mi_theap_t* theap, mi_page_t* page)
278	{
279	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
280	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
281	  mi_assert_internal(mi_page_is_owned(page));
282	  mi_assert_internal(mi_page_is_abandoned(page));
283	
284	  mi_page_set_theap(page,theap);
285	  _mi_page_free_collect(page, false); // ensure used count is up to date
286	  mi_page_queue_t* pq = mi_theap_page_queue_of(theap, page);
287	  mi_page_queue_push_at_end(theap, pq, page);
288	  mi_assert_expensive(_mi_page_is_valid(page));
289	}
290	
291	void _mi_page_abandon(mi_page_t* page, mi_page_queue_t* pq) {
292	  _mi_page_free_collect(page, false); // ensure used count is up to date
293	  if (mi_page_all_free(page)) {
294	    _mi_page_free(page, pq);
295	  }
296	  else {
297	    mi_page_queue_remove(pq, page);
298	    mi_theap_t* theap = page->theap;
299	    mi_page_set_theap(page, NULL);
300	    page->theap = theap; // don't actually set theap to NULL so we can reclaim_on_free within the same theap
301	    _mi_arenas_page_abandon(page, theap);
302	    // _mi_arenas_collect(false, false, theap->tld); // allow purging
303	  }
304	}
305	
306	
307	// allocate a fresh page from an arena
308	static mi_page_t* mi_page_fresh_alloc(mi_theap_t* theap, mi_page_queue_t* pq, size_t block_size, size_t page_alignment) {
309	  #if !MI_HUGE_PAGE_ABANDON
310	  mi_assert_internal(pq != NULL);
311	  mi_assert_internal(mi_theap_contains_queue(theap, pq));
312	  mi_assert_internal(page_alignment > 0 || block_size > MI_LARGE_MAX_OBJ_SIZE || block_size == pq->block_size);
313	  #endif
314	  mi_page_t* page = _mi_arenas_page_alloc(theap, block_size, page_alignment);
315	  if (page == NULL) {
316	    // out-of-memory
317	    return NULL;
318	  }
319	  if (mi_page_is_abandoned(page)) {
320	    _mi_theap_page_reclaim(theap, page);
321	    if (!mi_page_immediate_available(page)) {
322	      if (mi_page_is_expandable(page)) {
323	        if (!mi_page_extend_free(theap, page)) {
324	          // cannot commit
325	          _mi_page_abandon(page,pq);
326	          return NULL;
327	        };
328	      }
329	      else {
330	        mi_assert(false); // should not happen?
331	        return NULL;
332	      }
333	    }
334	  }
335	  else if (pq != NULL) {
336	    mi_page_queue_push(theap, pq, page);
337	  }
338	  mi_assert_internal(pq!=NULL || mi_page_block_size(page) >= block_size);
339	  mi_assert_expensive(_mi_page_is_valid(page));
340	  return page;
341	}
342	
343	// Get a fresh page to use
344	static mi_page_t* mi_page_fresh(mi_theap_t* theap, mi_page_queue_t* pq) {
345	  mi_assert_internal(mi_theap_contains_queue(theap, pq));
346	  mi_page_t* page = mi_page_fresh_alloc(theap, pq, pq->block_size, 0);
347	  if (page==NULL) return NULL;
348	  mi_assert_internal(pq->block_size==mi_page_block_size(page));
349	  mi_assert_internal(pq==mi_theap_page_queue_of(theap, page));
350	  return page;
351	}
352	
353	
354	/* -----------------------------------------------------------
355	  Unfull, abandon, free and retire
356	----------------------------------------------------------- */
357	
358	// Move a page from the full list back to a regular list (called from thread-local mi_free)
359	void _mi_page_unfull(mi_page_t* page) {
360	  mi_assert_internal(page != NULL);
361	  mi_assert_expensive(_mi_page_is_valid(page));
362	  mi_assert_internal(mi_page_is_in_full(page));
363	  mi_assert_internal(!mi_page_theap(page)->allow_page_abandon);
364	  if (!mi_page_is_in_full(page)) return;
365	
366	  mi_theap_t* theap = mi_page_theap(page);
367	  mi_page_queue_t* pqfull = &theap->pages[MI_BIN_FULL];
368	  mi_page_set_in_full(page, false); // to get the right queue
369	  mi_page_queue_t* pq = mi_theap_page_queue_of(theap, page);
370	  mi_page_set_in_full(page, true);
371	  mi_page_queue_enqueue_from_full(pq, pqfull, page);
372	}
373	
374	static void mi_page_to_full(mi_page_t* page, mi_page_queue_t* pq) {
375	  mi_assert_internal(pq == mi_page_queue_of(page));
376	  mi_assert_internal(!mi_page_immediate_available(page));
377	  mi_assert_internal(!mi_page_is_in_full(page));
378	
379	  mi_theap_t* theap = mi_page_theap(page);
380	  if (theap->allow_page_abandon) {
381	    // abandon full pages (this is the usual case in order to allow for sharing of memory between theaps)
382	    _mi_page_abandon(page, pq);
383	  }
384	  else if (!mi_page_is_in_full(page)) {
385	    // put full pages in a theap local queue (this is for theaps that cannot abandon, for example, if the theap can be destroyed)
386	    mi_page_queue_enqueue_from(&mi_page_theap(page)->pages[MI_BIN_FULL], pq, page);
387	    _mi_page_free_collect(page, false);  // try to collect right away in case another thread freed just before MI_USE_DELAYED_FREE was set
388	  }
389	}
390	
391	
392	// Free a page with no more free blocks
393	void _mi_page_free(mi_page_t* page, mi_page_queue_t* pq) {
394	  mi_assert_internal(page != NULL);
395	  mi_assert_expensive(_mi_page_is_valid(page));
396	  mi_assert_internal(pq == mi_page_queue_of(page));
397	  mi_assert_internal(mi_page_all_free(page));
398	  // mi_assert_internal(mi_page_thread_free_flag(page)!=MI_DELAYED_FREEING);
399	
400	  // no more aligned blocks in here
401	  mi_page_set_has_interior_pointers(page, false);
402	
403	  // remove from the page list
404	  // (no need to do _mi_theap_delayed_free first as all blocks are already free)
405	  mi_page_queue_remove(pq, page);
406	
407	  // and free it
408	  mi_theap_t* theap = mi_page_theap(page); mi_assert_internal(theap!=NULL);
409	  mi_page_set_theap(page,NULL);
410	  _mi_arenas_page_free(page, theap);
411	  // _mi_arenas_collect(false, false, theap->tld);  // allow purging
412	}
413	
414	#define MI_RETIRE_CYCLES      (16)      /* keep a retired page around for about 16 "admin cycles" before free'ing it */
415	#define MI_RETIRE_MAX_PAGES   (3)       /* keep at most N pages per size bin as retired */
416	
417	// Retire a page with no more used blocks
418	// Important to not retire too quickly though as new
419	// allocations might coming.
420	//

