878	// Look for a page with free blocks of `size` but don't try to search or allocate
879	static inline mi_page_t* mi_page_queue_lookup_free_first(mi_theap_t* theap, mi_page_queue_t* pq) {
880	  mi_assert_internal(!mi_page_queue_is_huge(pq));
