979	/* -----------------------------------------------------------
980	  Users can register a deferred free function called
981	  when the `free` list is empty. Since the `local_free`
982	  is separate this is deterministically called after
983	  a certain number of allocations.
984	----------------------------------------------------------- */
985	
986	// The program should only install a single deferred free handler before doing allocation.
987	static _Atomic(void*) deferred_free; // is `mi_deferred_free_fun*` (but some platforms don't support atomic function pointers)
988	static _Atomic(void*) deferred_arg;   
989	
990	void _mi_deferred_free(mi_theap_t* theap, bool force) {
991	  theap->heartbeat++;
992	  mi_deferred_free_fun* const fun = (mi_deferred_free_fun*)mi_atomic_load_ptr_acquire(void,&deferred_free);
993	  if (fun != NULL && !theap->tld->recurse) {
994	    theap->tld->recurse = true;
995	    void* const arg = mi_atomic_load_ptr_acquire(void,&deferred_arg);  
996	    fun(force, theap->heartbeat, arg);
997	    theap->tld->recurse = false;
998	  }
999	}
1000	
1001	void mi_register_deferred_free(mi_deferred_free_fun* fn, void* arg) mi_attr_noexcept {
1002	  mi_atomic_store_ptr_release(void,&deferred_arg, arg);
1003	  mi_atomic_store_ptr_release(void,&deferred_free, (void*)fn);  
1004	}
